## Option 1 — Manual thunk

```ts
export const fetchProducts =
  () => async (dispatch: AppDispatch) => {
    dispatch(productsSlice.actions.setStatus('loading'));
    try {
      const res  = await fetch('/api/products');
      const data = await res.json();
      dispatch(productsSlice.actions.setProducts(data));
      dispatch(productsSlice.actions.setStatus('succeeded'));
    } catch (err) {
      dispatch(productsSlice.actions.setError(String(err)));
      dispatch(productsSlice.actions.setStatus('failed'));
    }
  };
```

## Option 2 — createAsyncThunk

```ts
export const fetchProducts = createAsyncThunk(
  'products/fetchAll',
  async () => {
    const res = await fetch('/api/products');
    if (!res.ok) throw new Error('Network error');
    return res.json() as Promise<Product[]>;
  },
);

// In the slice:
extraReducers: (builder) => {
  builder
    .addCase(fetchProducts.pending,   (state) => { state.status = 'loading'; })
    .addCase(fetchProducts.fulfilled, (state, { payload }) => {
      state.items  = payload;
      state.status = 'succeeded';
    })
    .addCase(fetchProducts.rejected,  (state, { error }) => {
      state.status = 'failed';
      state.error  = error.message ?? 'Unknown error';
    });
},
```

## Option 3 — RTK Query

```ts
export const productsApi = createApi({
  reducerPath: 'productsApi',
  baseQuery: fetchBaseQuery({ baseUrl: '/api' }),
  endpoints: (build) => ({
    getProducts: build.query<Product[], void>({
      query: () => 'products',
    }),
  }),
});

// Component:
const { data: products, isLoading, error } = productsApi.useGetProductsQuery();
```

RTK Query is the simplest option — no reducers, no extra actions, automatic caching.

